                                                        </td>
                                                        <td class="TableStyle-CompTable-HeadD-Column2-Header1"><span class="mc-variable compatibility-table-values.Heading:Supported variable">Supported</span>
                                                        </td>
                                                    </tr>
                                                </thead>
                                                <tbody>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Pro variable">FileMaker Pro</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Go variable">FileMaker Go</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:No variable">No</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:WebD variable">FileMaker WebDirect</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:No variable">No</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Server variable">FileMaker Server</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:Cloud variable">FileMaker Cloud</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyE-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:DAPI variable">FileMaker Data API</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyD-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                    <tr class="TableStyle-CompTable-Body-Body1">
                                                        <td class="TableStyle-CompTable-BodyB-Column1-Body1"><span class="mc-variable compatibility-table-values.Prod:CWP variable">Custom Web Publishing</span>
                                                        </td>
                                                        <td class="TableStyle-CompTable-BodyA-Column2-Body1"><span class="mc-variable compatibility-table-values.Supported:Yes variable">Yes</span>
                                                        </td>
                                                    </tr>
                                                </tbody>
                                            </table>
                                        </div>
                                        <h2 class="ref-orig-head" data-mc-autonum="Originated in version"><span class="autonumber"><span>Originated in version</span></span>&#160;</h2>
                                        <p class="or-origin">22.0</p>
                                        <h2 class="ref-desc-head" data-mc-autonum="Description"><span class="autonumber"><span>Description</span></span>&#160;</h2>
                                        <p>This script step exports records from a FileMaker table to a file in the JSON Lines (JSONL) format. JSONL is a structured text file format where each line contains a separate, complete JSON object. A primary use for this format is as training data to fine-tune an AI model.</p>
                                        <p>For each record in the current found set (or for each related record if <strong>Table</strong> specifies a related table), the script step saves a JSON object on a single line in the output file. The format depends on the <strong>Format for fine-tuning</strong> option.</p>
                                        <p class="note" data-mc-autonum="&lt;b&gt;Note &#160;&lt;/b&gt;"><span class="autonumber"><span><b>Note &#160;</b></span></span>Though shown below as multiple lines for clarity, each JSON object is on a single line in the JSONL file.</p>
                                        <table class="TableStyle-StandardTable" style="mc-table-style: url(''resources/tablestyles/standardtable.css'');" cellspacing="0">
                                            <col class="TableStyle-StandardTable-Column-Column1" style="width: 15%;" />
                                            <col class="TableStyle-StandardTable-Column-Column1" style="width: 85%;" />
                                            <thead>
                                                <tr class="TableStyle-StandardTable-Head-Header1">
                                                    <th class="TableStyle-StandardTable-HeadE-Column1-Header1">If <strong>Format for fine-tuning</strong> is</th>
                                                    <th class="TableStyle-StandardTable-HeadD-Column1-Header1">Output format is</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <tr class="TableStyle-StandardTable-Body-Body1">
                                                    <td class="TableStyle-StandardTable-BodyE-Column1-Body1">
                                                        <p><strong><strong>On</strong></strong>
                                                        </p>
                                                    </td>
                                                    <td class="TableStyle-StandardTable-BodyD-Column1-Body1">
                                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                                            <div style="mc-code-lang: JavaScript;" class="codeSnippetBody" data-mc-continue="False" data-mc-line-number-start="1" data-mc-use-line-numbers="False"><pre><code>{<br />&#160;&#160;<span style="color: #dd1144; ">"messages"</span> :&#160;<br />&#160;&#160;[<br />&#160;&#160;&#160;&#160;{<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"content"</span> : <span style="color: #dd1144; ">"&lt;System_Prompt_Field_Data&gt;"</span>,<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"role"</span> : <span style="color: #dd1144; ">"system"</span><br />&#160;&#160;&#160;&#160;},<br />&#160;&#160;&#160;&#160;{<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"content"</span> : <span style="color: #dd1144; ">"&lt;User_Prompt_Field_Data&gt;"</span>,<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"role"</span> : <span style="color: #dd1144; ">"user"</span><br />&#160;&#160;&#160;&#160;},<br />&#160;&#160;&#160;&#160;{<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"content"</span> : <span style="color: #dd1144; ">"&lt;Assistant_Field_Data&gt;"</span>,<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"role"</span> : <span style="color: #dd1144; ">"assistant"</span><br />&#160;&#160;&#160;&#160;}<br />&#160;&#160;]<br />}</code></pre>
                                                            </div>
                                                        </div>
                                                        <p>where:</p>
                                                        <ul>
                                                            <li>
                                                                <p>&lt;System_Prompt_Field_Data&gt; is the data specified by <strong>System Prompt</strong>.</p>
                                                            </li>
                                                            <li>
                                                                <p>&lt;User_Prompt_Field_Data&gt; is the data specified by <strong>User Prompt</strong>.</p>
                                                            </li>
                                                            <li>
                                                                <p>&lt;Assistant_Prompt_Field_Data&gt; is the data specified by <strong>Assistant Prompt</strong>.</p>
                                                            </li>
                                                        </ul>
                                                    </td>
                                                </tr>
                                                <tr class="TableStyle-StandardTable-Body-Body1">
                                                    <td class="TableStyle-StandardTable-BodyB-Column1-Body1">
                                                        <p><strong>Off</strong>
                                                        </p>
                                                    </td>
                                                    <td class="TableStyle-StandardTable-BodyA-Column1-Body1">
                                                        <p>&#160;</p>
                                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                                            <div style="mc-code-lang: JavaScript;" class="codeSnippetBody" data-mc-continue="False" data-mc-line-number-start="1" data-mc-use-line-numbers="False"><pre><code>{<br />&#160;&#160;<span style="color: #dd1144; ">"messages"</span> :&#160;<br />&#160;&#160;[<br />&#160;&#160;&#160;&#160;{<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"content"</span> : <span style="color: #dd1144; ">"&lt;Predefined_System_Prompt&gt;"</span>,<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"role"</span> : <span style="color: #dd1144; ">"system"</span><br />&#160;&#160;&#160;&#160;},<br />&#160;&#160;&#160;&#160;{<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"content"</span> : <span style="color: #dd1144; ">"&lt;FieldName1&gt;=&lt;Data1&gt;, &lt;FieldName2&gt;=&lt;Data2&gt;, ... "</span>,<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"role"</span> : <span style="color: #dd1144; ">"user"</span><br />&#160;&#160;&#160;&#160;},<br />&#160;&#160;&#160;&#160;{<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"content"</span> : <span style="color: #dd1144; ">"&lt;Completion_Field_Data&gt;"</span>,<br />&#160;&#160;&#160;&#160;&#160;&#160;<span style="color: #dd1144; ">"role"</span> : <span style="color: #dd1144; ">"assistant"</span><br />&#160;&#160;&#160;&#160;}<br />&#160;&#160;]<br />}</code></pre>
                                                            </div>
                                                        </div>
                                                        <p>where:</p>
                                                        <ul>
                                                            <li>
                                                                <p>&lt;Predefined_System_Prompt&gt; is a predefined system prompt.</p>
                                                            </li>
                                                            <li>
                                                                <p>&lt;FieldNameN&gt;=&lt;DataN&gt; is a field name and its data. Includes all fields in <strong>Table</strong>, except for the field specified by <strong>Completion Field</strong>.</p>
                                                            </li>
                                                            <li>
                                                                <p>&lt;Assistant_Prompt_Field_Data&gt; is the data specified by <strong>Completion Field</strong>.</p>
                                                            </li>
                                                        </ul>
                                                    </td>
                                                </tr>
                                            </tbody>
                                        </table>
                                        <h2 class="notes-head" data-mc-autonum="Notes"><span class="autonumber"><span>Notes</span></span>&#160;</h2>
                                        <ul>
                                            <li>
                                                <p>Field types are handled as follows: </p>
                                                <ul>
                                                    <li>
                                                        <p>Text and number fields are saved as JSON strings and numbers, respectively.</p>
                                                    </li>
                                                    <li>
                                                        <p> Date and time fields are saved as strings with the system locale formats used when the FileMaker&#160;Pro file was created.</p>
                                                    </li>
                                                    <li>
                                                        <p>Container fields are not supported and are skipped when the <strong>Format for fine-tuning</strong> option is Off. If this option is On, the name of the file in the container field is exported as a string, if present.</p>
                                                    </li>
                                                    <li>
                                                        <p>Calculation fields are saved based on their result type.</p>
                                                    </li>
                                                </ul>
                                            </li>
                                            <li>
                                                <p>When the <strong>Format for fine-tuning</strong> option is On:</p>
                                                <ul>
                                                    <li>
                                                        <p><strong>System Prompt</strong> is optional. If it isn''t specified or if its specified data is an empty value, the object for the system role is omitted in the JSONL file. </p>
                                                    </li>
                                                    <li>
                                                        <p><strong>User Prompt</strong> and <strong>Assistant Prompt</strong> are required. If their values are empty, the <code>content</code> values for the user and assistant <code>roles </code>are empty strings.</p>
                                                    </li>
                                                </ul>
                                            </li>
                                            <li>
                                                <p>When the <strong>Format for fine-tuning</strong> option is Off:</p>
                                                <ul>
                                                    <li>
                                                        <p><strong>Completion Field</strong> is required. If its value is empty for a record, the record is omitted in the JSONL file.</p>
                                                    </li>
                                                </ul>
                                            </li>
                                        </ul>
                                        <h2 class="ref-example1-head" data-mc-autonum="Example 1"><span class="autonumber"><span>Example 1</span></span>- Format for fine-tuning is Off</h2>
                                        <p>Saves data to a JSONL file with <strong>Format for fine-tuning</strong> turned off. The <span class="nowrap">Support_QA</span> table contains customer support questions and answers about FileMaker, as well as other data. </p>
                                        <p>The script goes to the <span class="nowrap">Support_QA</span> layout and shows all records. It then sets $filePath to the JSONL file to save to in the Documents directory.</p>
                                        <p>Finally, the script saves all the records in the <span class="nowrap">Support_QA</span> table, with data from the Answer field identified in the assistant object in each line.</p>
                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                            <div class="codeSnippetBody" data-mc-use-line-numbers="False" data-mc-line-number-start="1" data-mc-continue="False"><pre><code>Go to Layout [ "Support_QA" (Support_QA) ]<br />Show All Records<br /><br />Set Variable [ $filePath ; Value: Get(DocumentsPath) &amp; "support-qa.jsonl" ]<br /><br />Save Records as JSONL [ Format for fine-tuning: Off ; Table: "Support_QA" ; Completion Field: Support_QA::Answer ; "$filePath" ; Create folders: Off ]</code></pre>
                                            </div>
                                        </div>
                                        <p>A line for one record in the support-qa.jsonl file:</p>
                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                            <div style="mc-code-lang: JavaScript;" class="codeSnippetBody" data-mc-continue="False" data-mc-line-number-start="1" data-mc-use-line-numbers="False"><pre><code>{<span style="color: #dd1144; ">"messages"</span>: [{<span style="color: #dd1144; ">"role"</span>: <span style="color: #dd1144; ">"system"</span>,<span style="color: #dd1144; ">"content"</span>: <span style="color: #dd1144; ">"&lt;Predefined_System_Prompt&gt;"</span>},{<span style="color: #dd1144; ">"role"</span>: <span style="color: #dd1144; ">"user"</span>,<span style="color: #dd1144; ">"content"</span>: <span style="color: #dd1144; ">"Area=Scripting, Question=How do I create a new script in FileMaker Pro?, Version=3"</span>},{<span style="color: #dd1144; ">"role"</span>: <span style="color: #dd1144; ">"assistant"</span>,<span style="color: #dd1144; ">"content"</span>: <span style="color: #dd1144; ">"Go to Scripts menu &gt; Script Workspace, then ..."</span>}]}</code></pre>
                                            </div>
                                        </div>
                                        <h2 class="ref-examplen-head" data-mc-autonum="Example 2"><span class="autonumber"><span>Example 2</span></span><a name="fine-tuning-example"></a>- Save as JSONL for fine-tuning</h2>
                                        <p>Using the same <span class="nowrap">Support_QA</span> table as above, this example saves data from select fields to a JSONL&#160;file to be used for fine-tuning the AI&#160;model in <a href="fine-tune-model.html#jsonl-example" class="ParaNumOnly MCXref xref xrefParaNumOnly">Example 2</a> for the <a href="fine-tune-model.html" class="LinktoScriptStep MCXref xref xrefLinktoScriptStep">Fine-Tune Model script step</a>. </p>
                                        <p>The script goes to the <span class="nowrap">Support_QA</span> layout and performs a find to get the desired found set. It then sets $trainingFile to the JSONL file to save to in the Documents directory.</p>
                                        <p>Finally, the script saves the found set of records in the <span class="nowrap">Support_QA</span> table to a JSONL file, with data from the Question field for the User Prompt, from the Answer field for Assistant Prompt, and a text expression that includes the Version field for System Prompt.</p>
                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                            <div class="codeSnippetBody" data-mc-use-line-numbers="False" data-mc-line-number-start="1" data-mc-continue="False"><pre><code>Go to Layout [ "Support_QA" (Support_QA) ]<br />Perform Find [ Restore ]<br /><br />Set Variable [ $trainingFile ; Value: Get(DocumentsPath) &amp; "training_data.jsonl" ]<br /><br />Set Variable [ $systemPrompt ; Value: "Applies to all FileMaker Pro versions starting with: " &amp; Support_QA::Version ]<br /><br />Save Records as JSONL [ Format for fine-tuning: On ; Table: "Support_QA" ; System Prompt: $systemPrompt ; User Prompt: Support_QA::Question ; Assistant Prompt: Support_QA::Answer ; "$trainingFile" ; Create folders: Off ]</code></pre>
                                            </div>
                                        </div>
                                        <p>A line for one record in the training_data.jsonl file:</p>
                                        <div class="codeSnippet"><a class="codeSnippetCopyButton" role="button" href="javascript:void(0);">Copy</a>
                                            <div style="mc-code-lang: JavaScript;" class="codeSnippetBody" data-mc-continue="False" data-mc-line-number-start="1" data-mc-use-line-numbers="False"><pre><code>{<span style="color: #dd1144; ">"messages"</span>:[{<span style="color: #dd1144; ">"content"</span>:<span style="color: #dd1144; ">"Applies to all FileMaker Pro versions starting with: 3"</span>,<span style="color: #dd1144; ">"role"</span>:<span style="color: #dd1144; ">"system"</span>},{<span style="color: #dd1144; ">"content"</span>:<span style="color: #dd1144; ">"How do I create a new script in FileMaker Pro?"</span>,<span style="color: #dd1144; ">"role"</span>:<span style="color: #dd1144; ">"user"</span>},{<span style="color: #dd1144; ">"content"</span>:<span style="color: #dd1144; ">"Go to Scripts menu &gt; Script Workspace, then ..."</span>,<span style="color: #dd1144; ">"role"</span>:<span style="color: #dd1144; ">"assistant"</span>}]}</code></pre>
                                            </div>
                                        </div>
